def best_average(a: list[int], k: int) -> list[int]:
    import math

    n = len(a)
    S = [0] * (n + 1)
    for i in range(n):
        S[i + 1] = S[i] + a[i]

    def slope_le(i: int, p: int, j: int) -> bool:
        return (S[j] - S[i]) * (j - p) <= (S[j] - S[p]) * (j - i)

    def cross(u: int, v: int, w: int) -> int:
        return (v - u) * (S[w] - S[v]) - (S[v] - S[u]) * (w - v)

    hull: list[int] = []
    best_num = 0
    best_den = 1
    have = False

    for j in range(k, n + 1):
        x = j - k
        while len(hull) >= 2 and cross(hull[-2], hull[-1], x) <= 0:
            hull.pop()
        hull.append(x)

        lo = 0
        hi = len(hull) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if slope_le(hull[mid], hull[mid + 1], j):
                lo = mid + 1
            else:
                hi = mid
        l = hull[lo]
        num = S[j] - S[l]
        den = j - l
        if (not have) or num * best_den > best_num * den:
            best_num = num
            best_den = den
            have = True

    g = math.gcd(best_num, best_den)
    return [best_num // g, best_den // g]
